package cn.course.community;
import java.util.*;
import java.math.BigDecimal;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:progress-workbench;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","app.seed=true","app.seed-password=TestOnly!2026Long"})
@AutoConfigureMockMvc @Transactional
class ProgressWorkbenchTest {
 @Autowired MockMvc mvc;@Autowired Store s;@Autowired ProgressWorkbench w;@Autowired CommunityService domain;
 long uid(String n){return s.uid(n+"@example.test");}
 Map<String,Object> list(String who){return w.list(1,uid(who),"",0,0,"ALL","recent",1);}
 List<Map<String,Object>> items(Map<String,Object> d){return (List<Map<String,Object>>)d.get("items");}
 Map<String,Object> summary(Map<String,Object> d){return (Map<String,Object>)d.get("summary");}
 long n(Map<String,Object> d,String key){return ((Number)d.get(key)).longValue();}
 long version(long entry,int no,Integer score){long template=entry==1?1:2;long id=s.insert("INSERT INTO submission(entry_id,version_no,title,content_json,content_hash,rubric_version,idempotency_key,created_at) SELECT ?,?,title,content_json,content_hash,rubric_version,?,? FROM submission WHERE id=?",entry,no,"progress-version-"+entry+"-"+no,Store.now(),template);if(score!=null)grade(id,score);return id;}
 void grade(long sid,int score){s.db.update("UPDATE evaluation SET active=FALSE WHERE submission_id=?",sid);int rev=s.db.queryForObject("SELECT COUNT(*) FROM evaluation WHERE submission_id=?",Integer.class,sid)+1;s.db.update("INSERT INTO evaluation(submission_id,teacher_id,revision_no,details_json,dimensions_json,q_raw,q_final,gate_reason,summary,active,created_at) VALUES(?,?,?,'[]',?,?,?,'','进展验收评价',TRUE,?)",sid,uid("teacher"),rev,"{\"S\":"+score+",\"A\":"+score+",\"C\":"+score+",\"L\":"+score+"}",score,score,Store.now());}
 long draft(String title){long aid=s.insert("INSERT INTO assignment(course_id,title,requirements,due_at,rubric_version,created_at) VALUES(1,?,'仅用于功能验收','2099-01-01T00:00:00Z','four-dim-v1',?)",title,Store.now());return s.insert("INSERT INTO entry(assignment_id,author_id,title,draft_json,evidence_json,revision,updated_at) VALUES(?,?,?,'{\"type\":\"doc\",\"content\":[]}','[]',0,?)",aid,uid("student"),title,Store.now());}
 @Test void studentSeesOnlyOwnMetadata(){var r=list("student");assertEquals(1,r.get("total"));assertEquals(uid("student"),n(items(r).getFirst(),"author_id"));assertTrue(((List<?>)r.get("authors")).isEmpty());assertFalse(r.toString().contains("draft_json"));assertFalse(r.toString().contains("content_json"));assertFalse(r.toString().contains("password"));assertFalse(r.toString().contains("教师私有"));}
 @Test void staffSummaryUsesRealEntriesAndActiveGrades(){var r=list("teacher");assertEquals(2,r.get("total"));var st=summary(r);assertEquals(2,n(st,"entry_count"));assertEquals(2,n(st,"submissions"));assertEquals(1,n(st,"graded_entries"));assertEquals(1,n(st,"pending_versions"));assertEquals(1,n(st,"open_feedback"));assertEquals(76,((Number)st.get("latest_average")).doubleValue(),.001);}
 @Test void ungradedIsNotZero(){var st=summary(list("peer"));assertNull(st.get("latest_average"));assertEquals(0,n(st,"graded_entries"));assertNull(items(list("peer")).getFirst().get("latest_score"));}
 @Test void otherAuthorsEvenPublishedHaveNoPrivateProgressAccess()throws Exception{mvc.perform(get("/api/progress-entries/1").with(user("peer@example.test"))).andExpect(status().isForbidden());mvc.perform(get("/api/courses/1/progress-workbench?authorId="+uid("peer")).with(user("student@example.test"))).andExpect(status().isForbidden());assertNotNull(domain.getSubmission(1,uid("peer")));}
 @Test void anonymousAndOtherCourseDenied()throws Exception{mvc.perform(get("/api/courses/1/progress-workbench")).andExpect(status().isUnauthorized());for(String path:List.of("/api/courses/1/progress-workbench","/api/progress-entries/1"))mvc.perform(get(path).with(user("outsider@example.test"))).andExpect(status().isForbidden());}
 @Test void assistantHasReadOnlyProgressNotTeacherDraft()throws Exception{s.db.update("INSERT INTO course_member(course_id,user_id,role) VALUES(1,?,'ASSISTANT')",uid("outsider"));assertEquals(2,list("outsider").get("total"));assertEquals("ASSISTANT",w.detail(1,uid("outsider"),1,1,"ALL").get("role"));mvc.perform(get("/api/submissions/1/review-draft").with(user("outsider@example.test"))).andExpect(status().isForbidden());}
 @Test void assignmentAndAuthorFiltersDontLeakOtherCourse(){assertEquals(1,w.list(1,uid("teacher"),"",1,uid("student"),"ALL","recent",1).get("total"));assertEquals(0,w.list(1,uid("teacher"),"",999,0,"ALL","recent",1).get("total"));assertEquals(0,w.list(1,uid("teacher"),"",0,uid("outsider"),"ALL","recent",1).get("total"));}
 @Test void searchTreatsWildcardsLiterally(){draft("100%_材料!");assertEquals(1,w.list(1,uid("teacher"),"%_",0,0,"ALL","recent",1).get("total"));assertEquals(0,w.list(1,uid("teacher"),"不存在%",0,0,"ALL","recent",1).get("total"));assertEquals(1,w.list(1,uid("teacher"),"周同学",0,0,"ALL","recent",1).get("total"));}
 @Test void statusCountsAndScopeSummaryIndependentOfStatus(){draft("仅草稿验收");var r=w.list(1,uid("teacher"),"",0,0,"DRAFT","recent",1);assertEquals(1,r.get("total"));assertEquals(3,n(summary(r),"entry_count"));assertEquals(1,n(summary(r),"draft_entries"));assertEquals(1,w.list(1,uid("teacher"),"",0,0,"PENDING","recent",1).get("total"));assertEquals(1,w.list(1,uid("teacher"),"",0,0,"FEEDBACK","recent",1).get("total"));}
 @Test void averageUsesLatestGradedPerEntryNotAllSubmissions(){version(1,2,90);grade(2,50);assertEquals(70,((Number)summary(list("teacher")).get("latest_average")).doubleValue(),.001);assertEquals(3,n(summary(list("teacher")),"submissions"));}
 @Test void oldGradedScoreRetainedBeyondRecentFive(){for(int i=2;i<=8;i++)version(1,i,null);var row=items(list("student")).getFirst();var recent=(List<Map<String,Object>>)row.get("versions");assertEquals(5,recent.size());assertEquals(4,n(recent.getFirst(),"version_no"));assertEquals(8,n(recent.getLast(),"version_no"));assertEquals(76,((Number)row.get("latest_score")).doubleValue(),.001);assertNotNull(row.get("latest_dimensions"));}
 @Test void regradeChangesScoreNotVersionCount(){long before=n(summary(list("student")),"submissions");grade(1,85);var st=summary(list("student"));assertEquals(before,n(st,"submissions"));assertEquals(85,((Number)st.get("latest_average")).doubleValue(),.001);assertEquals(2,n(((List<Map<String,Object>>)w.detail(1,uid("student"),1,1,"OPEN").get("versions")).getFirst(),"evaluation_revision"));}
 @Test void adoptionDoesNotResolveFeedback(){domain.action(1,"ADOPT","",uid("student"));assertEquals(1,n(summary(list("student")),"open_feedback"));var f=((List<Map<String,Object>>)w.detail(1,uid("student"),1,1,"OPEN").get("feedback")).getFirst();assertEquals("ADOPT",f.get("author_action"));assertEquals(false,f.get("resolved"));}
 @Test void teacherResolutionAndReopenRefreshCounts(){domain.action(1,"RESOLVE","已核对",uid("teacher"));assertEquals(0,n(summary(list("student")),"open_feedback"));assertEquals(0,w.detail(1,uid("student"),1,1,"OPEN").get("feedbackTotal"));assertEquals(1,w.detail(1,uid("student"),1,1,"RESOLVED").get("feedbackTotal"));domain.action(1,"REOPEN","需重新核对",uid("teacher"));assertEquals(1,n(summary(list("student")),"open_feedback"));}
 @Test void historicalFeedbackRemainsAfterNewSubmission(){version(1,2,90);assertEquals(1,n(summary(list("student")),"open_feedback"));var d=w.detail(1,uid("student"),1,1,"ALL");var f=((List<Map<String,Object>>)d.get("feedback")).getFirst();assertEquals(1,n(f,"version_no"));assertEquals("p-gap",f.get("paragraph_id"));assertEquals(1,n(f,"submission_id"));assertNotNull(f.get("original_text"));}
 @Test void entryPaginationAndStableScopeSummary(){for(int i=0;i<22;i++)draft("分页验收 "+i);var first=list("teacher");var second=w.list(1,uid("teacher"),"",0,0,"ALL","recent",2);assertEquals(24,first.get("total"));assertEquals(20,items(first).size());assertEquals(4,items(second).size());assertEquals(summary(first),summary(second));Set<Long> ids=new HashSet<>();for(var e:items(first))ids.add(n(e,"id"));for(var e:items(second))assertFalse(ids.contains(n(e,"id")));}
 @Test void versionsAndFeedbackAreServerPaged(){for(int i=2;i<=23;i++)version(1,i,null);for(int i=0;i<21;i++)domain.addFeedback(1,new ApiController.FeedbackRequest("p-gap","C2","轨迹反馈验收 "+i),uid("teacher"));var a=w.detail(1,uid("student"),1,1,"OPEN");var b=w.detail(1,uid("student"),2,2,"OPEN");assertEquals(23,a.get("versionTotal"));assertEquals(20,((List<?>)a.get("versions")).size());assertEquals(3,((List<?>)b.get("versions")).size());assertEquals(22,a.get("feedbackTotal"));assertEquals(2,((List<?>)b.get("feedback")).size());assertFalse(a.toString().contains("content_json"));}
 @Test void queryValidationAndMissingEntry()throws Exception{for(String q:List.of("page=0","page=100001","state=WRONG","sort=WRONG","assignmentId=-1","authorId=-1","q="+"x".repeat(81)))mvc.perform(get("/api/courses/1/progress-workbench?"+q).with(user("teacher@example.test"))).andExpect(status().isBadRequest());for(String q:List.of("versionPage=0","feedbackPage=0","feedbackState=WRONG","versionPage=100001"))mvc.perform(get("/api/progress-entries/1?"+q).with(user("teacher@example.test"))).andExpect(status().isBadRequest());mvc.perform(get("/api/progress-entries/999999").with(user("teacher@example.test"))).andExpect(status().isNotFound());}
 @Test void removedMemberDeniedButTeacherRetainsHistoricalEntry()throws Exception{s.db.update("DELETE FROM course_member WHERE course_id=1 AND user_id=?",uid("student"));mvc.perform(get("/api/courses/1/progress-workbench").with(user("student@example.test"))).andExpect(status().isForbidden());mvc.perform(get("/api/progress-entries/1").with(user("student@example.test"))).andExpect(status().isForbidden());assertEquals(2,list("teacher").get("total"));var authors=(List<Map<String,Object>>)list("teacher").get("authors");assertEquals(false,authors.stream().filter(a->n(a,"id")==uid("student")).findFirst().orElseThrow().get("current_member"));}
 @Test void qualitySortAndNoTeacherPrivateDraftLeak(){grade(2,92);var row=items(w.list(1,uid("teacher"),"",0,0,"ALL","quality",1)).getFirst();assertEquals(uid("peer"),n(row,"author_id"));assertFalse(list("teacher").toString().contains("review_draft"));assertEquals(1,n(items(w.list(1,uid("teacher"),"",0,0,"ALL","feedback",1)).getFirst(),"id"));}
}
